const state = {
  companyId: localStorage.getItem('policy-company'), companies: [], route: 'overview',
  refs: { groups: [], categories: [], policies: [], employees: [] },
  employeeQuery: { search: '', department: '', location: '', employmentType: '', status: '', manager: '', sort: 'name', direction: 'asc', offset: 0, limit: 50 },
  ruleQuery: { search: '', categoryId: '', dependency: '', status: '', offset: 0, limit: 50 },
  selectedEmployeeId: null, employeeTab: 'assignments', employeeFlow: null, ruleFlow: null,
};

const $ = (selector, root = document) => root.querySelector(selector);
const $$ = (selector, root = document) => [...root.querySelectorAll(selector)];
const main = $('#main-content');
const today = () => new Date().toISOString().slice(0, 10);
const esc = (value) => String(value ?? '').replace(/[&<>'"]/g, (character) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', "'": '&#39;', '"': '&quot;' })[character]);
const attr = (value) => esc(value).replace(/`/g, '&#96;');
const titleCase = (value) => String(value ?? '').toLowerCase().replace(/(^|[_\s-])\w/g, (match) => match.toUpperCase()).replaceAll('_', ' ');
const slug = (value) => String(value ?? '').trim().toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '').slice(0, 90) || `item-${Date.now()}`;
const number = (value) => new Intl.NumberFormat().format(Number(value ?? 0));
const dateTime = (value) => value ? new Intl.DateTimeFormat(undefined, { dateStyle: 'medium', timeStyle: 'short' }).format(new Date(value)) : '—';
const shortDate = (value) => value ? new Intl.DateTimeFormat(undefined, { month: 'short', day: 'numeric', year: 'numeric', timeZone: 'UTC' }).format(new Date(`${String(value).slice(0, 10)}T00:00:00Z`)) : '—';
const initials = (name) => String(name || '?').split(/\s+/).slice(0, 2).map((word) => word[0]).join('').toUpperCase();
function employeePrimary(employee) { return employee?.display_label || employee?.displayName || employee?.display_name || 'Employee'; }
function employeeContext(employee) { return employee?.context_label || employee?.contextLabel || [employee?.department, employee?.location].filter(Boolean).join(' · '); }
function employeeRecord(employee) { return employee?.record_label || employee?.recordLabel || (employee?.external_id ? `Employee ID ${employee.external_id}` : ''); }
function employeeIdentity(employee, options = {}) {
  const primary = employeePrimary(employee); const context = employeeContext(employee); const record = employeeRecord(employee);
  return `<div class="cell-primary employee-identity">${options.avatar === false ? '' : `<span class="avatar">${esc(initials(primary))}</span>`}<span class="cell-stack"><strong>${esc(primary)}</strong>${context ? `<small>${esc(context)}</small>` : ''}${record ? `<small class="record-label">${esc(record)}</small>` : ''}</span></div>`;
}
function relativeTime(value) {
  if (!value) return '—';
  const seconds = Math.round((new Date(value).getTime() - Date.now()) / 1000);
  const formatter = new Intl.RelativeTimeFormat(undefined, { numeric: 'auto' });
  if (Math.abs(seconds) < 60) return formatter.format(seconds, 'second');
  if (Math.abs(seconds) < 3600) return formatter.format(Math.round(seconds / 60), 'minute');
  if (Math.abs(seconds) < 86400) return formatter.format(Math.round(seconds / 3600), 'hour');
  return formatter.format(Math.round(seconds / 86400), 'day');
}

