  if (condition.type === 'not') return `not (${conditionSummary(condition.condition, groups)})`;
  if (condition.type === 'group') return `${condition.operator === 'MEMBER_OF' ? 'member of' : 'not a member of'} ${groups.find((group) => group.id === condition.groupId)?.name || 'group'}`;
  const fact = condition.fact.kind === 'employee' ? condition.fact.field : condition.fact.kind === 'attribute' ? condition.fact.key : condition.fact.kind;
  return `${factLabel(fact)} ${operatorLabel(condition.operator)} ${formatValue(condition.value)}`;
