  const opOptions = isGroup ? [['MEMBER_OF', 'is a member of'], ['NOT_MEMBER_OF', 'is not a member of']] : [['EQ', 'is'], ['NE', 'is not'], ['IN', 'is one of'], ['NOT_IN', 'is not one of'], ['GT', 'is greater than'], ['GTE', 'is at least'], ['LT', 'is less than'], ['LTE', 'is at most']];
  const rawValue = Array.isArray(condition.value) ? condition.value.join(', ') : condition.value;
  const valueControl = isGroup ? `<select data-rule-value="${path}">${state.refs.groups.map((group) => `<option value="${attr(group.id)}" ${condition.groupId === group.id ? 'selected' : ''}>${esc(group.name)}</option>`).join('')}</select>` : fact === 'employee:is_manager' ? `<select data-rule-value="${path}"><option value="true" ${condition.value === true ? 'selected' : ''}>Yes</option><option value="false" ${condition.value === false ? 'selected' : ''}>No</option></select>` : fact === 'attribute:custom' ? `<span class="condition-value-pair"><input data-rule-attribute-key="${path}" placeholder="Attribute key" /><input data-rule-value="${path}" value="${attr(rawValue)}" placeholder="Value" /></span>` : `<input data-rule-value="${path}" value="${attr(rawValue)}" placeholder="Value" ${fact === 'tenure_days' ? 'type="number" min="0" step="1"' : fact === 'as_of_date' || fact === 'employee:hire_date' ? 'type="date"' : ''}/>`;
