    ...result.ruleChanges.map((item) => { const priorityChanged = item.before.priority !== item.after.priority; const enabledChanged = item.before.enabled !== item.after.enabled; return { at: item.occurred_at, icon: 'rules', title: `Rule changed · ${titleCase(item.rule_key)}`, detail: priorityChanged ? `Priority ${item.before.priority} → ${item.after.priority}` : enabledChanged ? `${item.after.enabled ? 'Enabled' : 'Disabled'} · assigns ${item.policy_name}` : `Conditions or effective dates changed · assigns ${item.policy_name}`, ruleId: item.rule_id }; }),
