    ...result.overrides.map((item) => ({ at: item.occurred_at, icon: 'override', title: `Manual override ${item.revoked_at ? 'removed' : 'added'} · ${item.employee_name}`, detail: `${item.action === 'ASSIGN' ? 'Always assign' : 'Always exclude'} ${item.policy_name} · ${item.reason}`, record: item.employee_record_label, employeeId: item.employee_id })),
